<?php require 'includes/functions.php';$title='Inscription';$base='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$n=trim($_POST['name']??'');$em=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';if(!$n||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)flash('Informations invalides. Mot de passe : 8 caractères minimum.','danger');else{try{$s=$pdo->prepare("INSERT INTO users(full_name,email,password_hash) VALUES(?,?,?)");$s->execute([$n,$em,password_hash($pw,PASSWORD_DEFAULT)]);flash('Compte créé. Connectez-vous.');go('login.php');}catch(PDOException $e){flash('Adresse e-mail déjà utilisée.','danger');}}}require 'includes/header.php';?><section class="container section"><form class="form auth" method="post"><h1>Créer un compte</h1><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Nom complet<input required name="name"></label><label>E-mail<input required type="email" name="email"></label><label>Mot de passe<input required type="password" minlength="8" name="password"></label><button class="btn full">S'INSCRIRE</button><p>Déjà inscrit ? <a href="login.php">Connexion</a></p></form></section><?php require 'includes/footer.php';?>
